from fractions import Fraction

def _round_half_up(x):
    return (2 * x.numerator + x.denominator) // (2 * x.denominator)

def solve(facts):
    subtotal = 0
    for line in facts['lines']:
        discount = Fraction(line['discount_percent'])
        amount = Fraction(line['qty'] * line['unit_cents']) * (1 - discount / 100)
        subtotal += _round_half_up(amount)
    tax = _round_half_up(Fraction(subtotal) * Fraction(facts['tax_percent']) / 100)
    return {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}

def check(answer, facts):
    subtotal = 0
    for line in facts['lines']:
        q = Fraction(line['discount_percent'])
        numerator = line['qty'] * line['unit_cents'] * (100 * q.denominator - q.numerator)
        denominator = 100 * q.denominator
        subtotal += (2 * numerator + denominator) // (2 * denominator)
    t = Fraction(facts['tax_percent'])
    numerator = subtotal * t.numerator
    denominator = 100 * t.denominator
    tax = (2 * numerator + denominator) // (2 * denominator)
    expected = {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}
    return isinstance(answer, dict) and answer == expected
